import {WARM_PARAMS,WARM_PRESETS,freshWarm,validateWarm} from './warm.mjs';

const $=id=>document.getElementById(id),storageKey='small-machines-warm-v1',copy=x=>structuredClone(x);
let project=freshWarm(),ctx,node,analyser,initializing,playing=false,recording=false,recordStarting=false;
let worker,exportChunks=[],takeChunks=[],takeURL,recordSeconds=0,intent=0,saveTimer,editBar=0,editStep=0,baseNote=48;
let state={playing:false,bar:-1,step:-1,voices:0,meters:[0,0],seconds:0};
const held=new Map(),sounding=new Set(),keyEls=new Map(),stepEls=[],controlEls=new Map();
const tell=(message,error=false)=>{$('warm-status').textContent=message;$('warm-status').dataset.error=String(error);};
try{const saved=localStorage.getItem(storageKey);if(saved)project=validateWarm(JSON.parse(saved));}catch{tell('Das gespeicherte Pattern konnte nicht geladen werden. Bernsteinfenster ist bereit.',true);}
const send=data=>node?.port.postMessage(data),clock=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`;
const noteNames=['C','C♯','D','D♯','E','F','F♯','G','G♯','A','B♭','B'],noteName=n=>noteNames[n%12]+(Math.floor(n/12)-1);
const keyMap={a:0,w:1,s:2,e:3,d:4,f:5,t:6,g:7,y:8,z:8,h:9,u:10,j:11,k:12};
function persist(){clearTimeout(saveTimer);try{localStorage.setItem(storageKey,JSON.stringify(project));$('warm-save-state').textContent='Klang und acht Takte auf diesem Gerät gespeichert.';}catch{$('warm-save-state').textContent='Browser-Speicher nicht verfügbar. Bitte „Klang + Pattern“ herunterladen.';}}
function save(){clearTimeout(saveTimer);saveTimer=setTimeout(persist,180);$('warm-preset').value='custom';}
function paintHeld(){for(const [note,el]of keyEls)el.classList.toggle('held',[...held.values()].includes(note));}
function release(source){const note=held.get(source);if(note===undefined)return;held.delete(source);if(![...held.values()].includes(note)){send({type:'off',note});sounding.delete(note);}paintHeld();}
function releaseAll(){for(const note of new Set(held.values()))send({type:'off',note});held.clear();sounding.clear();paintHeld();}
async function press(source,note){if(held.has(source))return;held.set(source,note);paintHeld();try{await audio();if(held.get(source)!==note)return;$('warm-session-audio').pause();if(!sounding.has(note)){send({type:'on',note,velocity:.8});sounding.add(note);}}catch(e){release(source);tell(e.message,true);}}

const specs={
 saw:['SÄGEZAHN','%','Licht und Obertöne'],pulse:['PULSWELLE','%','Die zweite Farbe'],sub:['SUB','%','Eine Oktave darunter'],noise:['RAUSCHEN','%','Ein wenig Luft'],pulseWidth:['PULSBREITE','%','Von hohl bis schmal'],pwm:['PWM','%','Bewegung der Pulsbreite'],
 cutoff:['CUTOFF','Hz','Den Klang öffnen'],resonance:['RESONANZ','%','Farbe an der Filterkante'],env:['ENV MOD','%','Die Hüllkurve bewegt den Filter'],hpf:['HOCHPASS','Hz','Platz für tiefe Stimmen'],
 attack:['ATTACK','ms','Zeit zum Aufblühen'],decay:['DECAY','ms','Vom Anfang zum Halten'],sustain:['SUSTAIN','%','Der stehende Klang'],release:['RELEASE','ms','Zeit zum Verabschieden'],
 chorus:['CHORUS','%','Ein breiter, weicher Schimmer'],drift:['DRIFT','ct','Kleine Tonhöhenschwankungen'],lfoRate:['LFO RATE','Hz','Langsame Bewegung'],volume:['LEVEL','%','Ausgangslautstärke']
};
const groups=[['OSZILLATOR',['saw','pulse','sub','noise','pulseWidth','pwm']],['FILTER',['cutoff','resonance','env','hpf']],['HÜLLKURVE',['attack','decay','sustain','release']],['BEWEGUNG',['chorus','drift','lfoRate','volume']]];
const logarithmic=new Set(['cutoff','hpf','attack','decay','release','lfoRate']);
function formatParam(key,value){const unit=specs[key]?.[1]||'';if(unit==='Hz'&&value>=1000)return(value/1000).toFixed(2)+' kHz';if(unit==='ms'&&value>=1000)return(value/1000).toFixed(2)+' s';return(key==='lfoRate'?value.toFixed(2):Math.round(value))+' '+unit;}
for(const [title,keys]of groups){const group=document.createElement('section');group.className='warm-control-group';const heading=document.createElement('h3');heading.textContent=title;group.append(heading);for(const key of keys){if(!WARM_PARAMS[key])continue;const [label,,hint]=specs[key],id='warm-param-'+key,[min,max]=WARM_PARAMS[key],box=document.createElement('div');box.className='warm-control';box.innerHTML=`<label for="${id}">${label}<output></output></label><input id="${id}" type="range"><p>${hint}</p>`;const input=box.querySelector('input'),output=box.querySelector('output');input.min=logarithmic.has(key)?0:min;input.max=logarithmic.has(key)?1000:max;input.step=1;input.oninput=()=>{let value=logarithmic.has(key)?min*(max/min)**(Number(input.value)/1000):Number(input.value);value=key==='lfoRate'?Math.round(value*100)/100:Math.round(value);project.params[key]=Math.max(min,Math.min(max,value));output.textContent=formatParam(key,project.params[key]);send({type:'param',key,value:project.params[key]});save();};group.append(box);controlEls.set(key,{input,output});}$('warm-controls').append(group);}
WARM_PRESETS.forEach((p,i)=>$('warm-preset').add(new Option(p.name,String(i))));$('warm-preset').add(new Option('Dein Klang','custom'));
for(let b=0;b<8;b++)$('warm-bar').add(new Option(String(b+1).padStart(2,'0')+' / 08',String(b)));
for(let i=0;i<16;i++){const button=document.createElement('button');button.className='warm-step';button.innerHTML=`<span>${String(i+1).padStart(2,'0')}</span><strong>—</strong><small>KEIN TRIGGER</small>`;button.onclick=()=>{editStep=i;paintSteps();paintEvent();};$('warm-steps').append(button);stepEls.push(button);}
function paintSteps(){for(let i=0;i<16;i++){const e=project.patterns[editBar][i],b=stepEls[i];b.classList.toggle('event',!!e);b.classList.toggle('current',playing&&state.bar===editBar&&state.step===i);b.setAttribute('aria-pressed',String(i===editStep));b.setAttribute('aria-label',`Schritt ${i+1}: ${e?e.notes.map(noteName).join(', '):'leer'}`);b.querySelector('strong').textContent=e?e.notes.map(noteName).join(' · '):'—';b.querySelector('small').textContent=e?`${e.length} × 1/16`:'KEIN TRIGGER';}}
function paintEvent(){const e=project.patterns[editBar][editStep];$('warm-edit-position').textContent=`TAKT ${String(editBar+1).padStart(2,'0')} / SCHRITT ${String(editStep+1).padStart(2,'0')}`;$('warm-notes').value=e?e.notes.join(', '):'';$('warm-length').value=e?.length??8;$('warm-velocity').value=Math.round((e?.velocity??.75)*100);$('warm-velocity-value').textContent=$('warm-velocity').value+'%';$('warm-note-names').textContent=e?e.notes.map(noteName).join(' · '):'Noch kein Akkord';}
function buildKeyboard(){releaseAll();keyEls.clear();$('warm-keyboard').replaceChildren();let whites=0;for(let offset=0;offset<24;offset++){const n=baseNote+offset,black=[1,3,6,8,10].includes(n%12),b=document.createElement('button');b.className='warm-key '+(black?'black':'white');b.setAttribute('aria-label','Note '+noteName(n));b.dataset.note=n;b.innerHTML='<span>'+noteName(n)+'</span>';if(black)b.style.left=(whites/14*100)+'%';else whites++;b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);void press('pointer-'+e.pointerId,n);};b.onpointerup=e=>release('pointer-'+e.pointerId);b.onpointercancel=e=>release('pointer-'+e.pointerId);b.onlostpointercapture=e=>release('pointer-'+e.pointerId);b.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();if(!e.repeat)void press('button-'+n,n);}};b.onkeyup=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();release('button-'+n);}};b.onblur=()=>release('button-'+n);$('warm-keyboard').append(b);keyEls.set(n,b);}$('warm-octave').textContent=noteName(baseNote)+'–'+noteName(baseNote+23);$('warm-octave-down').disabled=baseNote<=24;$('warm-octave-up').disabled=baseNote>=72;}
function paint(){ $('warm-name').value=project.name;$('warm-display-name').textContent=project.name.toUpperCase();$('warm-bpm').value=project.bpm;for(const [key,{input,output}]of controlEls){const value=project.params[key],[min,max]=WARM_PARAMS[key];input.value=logarithmic.has(key)?Math.log(value/min)/Math.log(max/min)*1000:value;output.textContent=formatParam(key,value);}const index=WARM_PRESETS.findIndex((p,i)=>JSON.stringify(freshWarm(i))===JSON.stringify(project));$('warm-preset').value=index<0?'custom':String(index);paintSteps();paintEvent();transport();}
const mutationIds=['warm-preset','warm-bpm','warm-apply-step','warm-clear-step','warm-clear-bar','warm-import-project','warm-name'];
function transport(){$('warm-play').textContent=playing?'Ⅱ Pattern anhalten':'▶ '+(ctx?'Spielen':'Einschalten & spielen');$('warm-record').setAttribute('aria-pressed',String(recording));$('warm-record').textContent=recording?'■ '+clock(recordSeconds):recordStarting?'AUDIO STARTET …':'● REC';$('warm-record').disabled=!!worker||recordStarting;$('warm-export-wav').disabled=!!worker||recording||recordStarting;for(const id of mutationIds)$(id).disabled=recording||recordStarting;$('warm-position').textContent=playing?`TAKT ${String(state.bar+1).padStart(2,'0')} / 08`:'BEREIT';}
async function audio(){if(initializing)return initializing;if(ctx&&node){await ctx.resume();return;}
 initializing=(async()=>{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('Web Audio ist in diesem Browser nicht verfügbar.');ctx=new Audio();await ctx.resume();if(!ctx.audioWorklet)throw Error('Live-Audio braucht AudioWorklet über HTTPS oder localhost. Bitte die veröffentlichte Studio-Seite öffnen.');await ctx.audioWorklet.addModule('./warm-worklet.mjs');node=new AudioWorkletNode(ctx,'small-warm',{numberOfInputs:0,numberOfOutputs:1,outputChannelCount:[2]});node.port.onmessage=receive;analyser=ctx.createAnalyser();analyser.fftSize=512;node.connect(analyser);analyser.connect(ctx.destination);send({type:'load',data:project});node.onprocessorerror=()=>{const failed=ctx;node?.disconnect();node=null;analyser=null;ctx=null;void failed?.close();playing=false;recording=false;recordStarting=false;held.clear();sounding.clear();paintHeld();transport();tell('Audio wurde unterbrochen. Bitte erneut einschalten.',true);};ctx.onstatechange=()=>{$('warm-audio-state').textContent=ctx?.state==='running'?`${(ctx.sampleRate/1000).toFixed(1)} kHz / AUDIO AN`:'AUDIO PAUSIERT';};$('warm-audio-state').textContent=`${(ctx.sampleRate/1000).toFixed(1)} kHz / AUDIO AN`;})();
 try{await initializing;}catch(e){node?.disconnect();node=null;analyser=null;const failed=ctx;ctx=null;if(failed)await failed.close();throw e;}finally{initializing=null;}
}
async function start(){const token=++intent;try{await audio();if(token!==intent)return;$('warm-session-audio').pause();send({type:'play'});playing=true;transport();tell('Das Pattern spielt. Die Klaviatur und alle Klangregler bleiben live.');}catch(e){tell(e.message,true);}}
function stop(){intent++;releaseAll();send({type:'stop'});playing=false;state.step=-1;paintSteps();transport();tell(recording?'Das Pattern steht; der Take nimmt den Ausklang weiter auf. REC beendet ihn.':'Gestoppt. Die Stimmen dürfen ausklingen.');}
function patternChanged(message){intent++;releaseAll();send({type:'stop'});playing=false;state={...state,bar:-1,step:-1};send({type:'load',data:project});save();paint();tell(message+' Play beginnt wieder bei Takt 1.');}
$('warm-play').onclick=()=>playing?stop():start();$('warm-stop').onclick=stop;$('warm-panic').onclick=()=>{intent++;releaseAll();playing=false;send({type:'panic'});state={...state,bar:-1,step:-1,voices:0};transport();paintSteps();tell('Sofort stumm.');};
$('warm-record').onclick=async()=>{if(recording){send({type:'recordStop'});return;}if(recordStarting||worker)return;recordStarting=true;const token=++intent;transport();try{await audio();if(token!==intent)return;takeChunks=[];recordSeconds=0;recording=true;$('warm-session-audio').pause();send({type:'record'});if(!playing){send({type:'play'});playing=true;}tell('REC läuft. Tastenspiel und Reglerbewegungen werden mit aufgenommen.');}catch(e){recording=false;tell(e.message,true);}finally{recordStarting=false;transport();}};
function receive(e){const d=e.data;if(d.type==='state'){state=d.state;playing=state.playing;recordSeconds=d.recordSeconds||0;$('warm-voices').textContent=`${state.voices} / 6 STIMMEN`;transport();paintSteps();}else if(d.type==='chunk')takeChunks.push(d.chunk);else if(d.type==='recordDone'){recording=false;transport();if(d.frames){setDownload(new Blob([wavHeader(d.frames,d.rate),...takeChunks],{type:'audio/wav'}),'Live-Take');tell(`Aufnahme bereit: ${clock(d.frames/d.rate)}. Über den Download-Link speichern.`);}takeChunks=[];}else if(d.type==='error'){playing=false;recording=false;recordStarting=false;held.clear();sounding.clear();paintHeld();transport();tell(d.message,true);}}
$('warm-preset').onchange=()=>{if($('warm-preset').value==='custom')return;project=freshWarm(Number($('warm-preset').value));editBar=editStep=0;$('warm-bar').value='0';patternChanged(project.name+' geladen.');};
$('warm-bpm').onchange=()=>{project.bpm=Math.round(Math.max(40,Math.min(220,Number($('warm-bpm').value)||92)));patternChanged('Tempo gespeichert.');};
$('warm-name').onchange=()=>{project.name=$('warm-name').value.trim()||'Mein warmer Klang';$('warm-display-name').textContent=project.name.toUpperCase();save();};
$('warm-bar').onchange=()=>{editBar=Number($('warm-bar').value);paintSteps();paintEvent();};
$('warm-velocity').oninput=()=>$('warm-velocity-value').textContent=$('warm-velocity').value+'%';
for(const b of document.querySelectorAll('.warm-chord-starters button'))b.onclick=()=>{$('warm-notes').value=b.dataset.notes;$('warm-note-names').textContent=b.dataset.notes.split(',').map(Number).map(noteName).join(' · ');};
$('warm-apply-step').onclick=()=>{if(recording||recordStarting)return;try{const raw=$('warm-notes').value.trim();if(!raw)throw Error('Bitte eine bis sechs MIDI-Noten eintragen, zum Beispiel 60, 64, 67.');const notes=raw.split(/[\s,;]+/).map(Number);if(notes.length>6||notes.some(n=>!Number.isInteger(n)||n<24||n>96)||new Set(notes).size!==notes.length)throw Error('Erlaubt sind eine bis sechs verschiedene ganze MIDI-Noten von 24 bis 96.');const length=Number($('warm-length').value),velocity=Number($('warm-velocity').value)/100;if(!Number.isFinite(length)||length<1||length>32)throw Error('Die Länge liegt zwischen 1 und 32 Sechzehnteln.');project.patterns[editBar][editStep]={notes,velocity,length};validateWarm(project);patternChanged('Akkord gesetzt.');}catch(e){tell(e.message,true);}};
$('warm-clear-step').onclick=()=>{if(recording||recordStarting)return;project.patterns[editBar][editStep]=null;patternChanged('Schritt geleert.');};$('warm-clear-bar').onclick=()=>{if(recording||recordStarting)return;project.patterns[editBar]=Array(16).fill(null);patternChanged('Dieser Takt ist jetzt leer.');};
$('warm-octave-down').onclick=()=>{baseNote=Math.max(24,baseNote-12);buildKeyboard();};$('warm-octave-up').onclick=()=>{baseNote=Math.min(72,baseNote+12);buildKeyboard();};
const filename=()=>project.name.replace(/[^\p{L}\p{N}_-]+/gu,'-').slice(0,70)||'WARM06';
function wavHeader(frames,rate){const buffer=new ArrayBuffer(44),view=new DataView(buffer),text=(i,s)=>{for(let j=0;j<s.length;j++)view.setUint8(i+j,s.charCodeAt(j));};text(0,'RIFF');view.setUint32(4,36+frames*4,true);text(8,'WAVEfmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,2,true);view.setUint32(24,rate,true);view.setUint32(28,rate*4,true);view.setUint16(32,4,true);view.setUint16(34,16,true);text(36,'data');view.setUint32(40,frames*4,true);return buffer;}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);}
function setDownload(blob,suffix){if(takeURL)URL.revokeObjectURL(takeURL);takeURL=URL.createObjectURL(blob);const a=$('warm-take-download');a.href=takeURL;a.download=filename()+'-'+suffix+'.wav';a.textContent='↓ '+suffix+' herunterladen';a.hidden=false;}
$('warm-export-project').onclick=()=>download(new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),filename()+'-WARM06.json');$('warm-import-project').onclick=()=>$('warm-file').click();
$('warm-file').onchange=async()=>{try{if(recording||recordStarting)return;const f=$('warm-file').files[0];if(!f)return;if(f.size>1000000)throw Error('Die Klangdatei ist zu groß (max. 1 MB).');const incoming=validateWarm(JSON.parse(await f.text()));if(recording||recordStarting)throw Error('Bitte die Aufnahme zuerst beenden.');project=incoming;editBar=editStep=0;$('warm-bar').value='0';patternChanged('Klang und Pattern geladen.');}catch(e){tell(e.message,true);}finally{$('warm-file').value='';}};
$('warm-to-ensemble').onclick=()=>{try{localStorage.setItem('small-machines-warm-transfer',JSON.stringify(validateWarm(project)));$('warm-ensemble-link').hidden=false;tell('Bereit für das Ensemble: Dort eine Szene wählen und „WARM/06 übernehmen“ anklicken.');}catch{tell('Die Übergabe konnte nicht gespeichert werden. Bitte „Klang + Pattern“ herunterladen und im Ensemble laden.',true);}};
function finishExport(){worker?.terminate();worker=null;$('warm-export-progress').hidden=true;$('warm-cancel-export').hidden=true;transport();}
$('warm-export-wav').onclick=()=>{if(worker||recording||recordStarting)return;exportChunks=[];$('warm-export-progress').hidden=false;$('warm-export-progress').value=0;$('warm-cancel-export').hidden=false;try{worker=new Worker('./warm-render-worker.mjs',{type:'module'});transport();tell('Acht Takte werden als Stereo-WAV berechnet.');worker.onmessage=e=>{const d=e.data;if(d.type==='chunk'){exportChunks.push(d.chunk);$('warm-export-progress').value=d.progress;}else if(d.type==='done'){setDownload(new Blob([wavHeader(d.frames,d.rate),...exportChunks],{type:'audio/wav'}),'8-Takte');exportChunks=[];finishExport();tell('WAV bereit. Über den Download-Link speichern.');}else if(d.type==='error'){exportChunks=[];finishExport();tell(d.message,true);}};worker.onerror=()=>{exportChunks=[];finishExport();tell('Der WAV-Export wurde unterbrochen.',true);};worker.postMessage({data:copy(project),bars:8});}catch(e){finishExport();tell(e.message,true);}};
$('warm-cancel-export').onclick=()=>{exportChunks=[];finishExport();tell('Export abgebrochen.');};
$('warm-session-audio').onplay=()=>{if(recording||recordStarting){$('warm-session-audio').pause();tell('Bitte zuerst den Take beenden.');return;}stop();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('warm-panic').click();return;}if(e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,select,textarea,button,a,audio'))return;if(e.code==='Space'){e.preventDefault();if(!e.repeat)$('warm-play').click();return;}const key=e.key.toLowerCase();if(Object.hasOwn(keyMap,key)){e.preventDefault();if(!e.repeat)void press('keyboard-'+e.code,baseNote+keyMap[key]);}});
document.addEventListener('keyup',e=>release('keyboard-'+e.code));window.addEventListener('blur',releaseAll);document.addEventListener('visibilitychange',()=>{if(document.hidden)releaseAll();});window.addEventListener('pagehide',()=>{intent++;releaseAll();send({type:'panic'});persist();});
buildKeyboard();paint();
const canvas=$('warm-scope'),g=canvas.getContext('2d'),samples=new Uint8Array(512);samples.fill(128);let lastDraw=0;
function draw(t){if(!document.hidden&&t-lastDraw>60){lastDraw=t;const width=canvas.clientWidth,height=canvas.clientHeight,ratio=Math.min(devicePixelRatio||1,2);if(width&&height){if(canvas.width!==Math.round(width*ratio)||canvas.height!==Math.round(height*ratio)){canvas.width=Math.round(width*ratio);canvas.height=Math.round(height*ratio);}g.setTransform(ratio,0,0,ratio,0,0);g.clearRect(0,0,width,height);g.strokeStyle='#314231';g.lineWidth=1;g.beginPath();g.moveTo(0,height/2);g.lineTo(width,height/2);g.stroke();if(analyser)analyser.getByteTimeDomainData(samples);else samples.fill(128);g.strokeStyle='#d2b67e';g.lineWidth=1.3;g.beginPath();for(let i=0;i<samples.length;i++){const x=i/(samples.length-1)*width,y=height/2+(samples[i]-128)/128*height*.43;i?g.lineTo(x,y):g.moveTo(x,y);}g.stroke();}}requestAnimationFrame(draw);}requestAnimationFrame(draw);
